/* ÇEVİRİ de · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("de","olay",{
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Griechen von der Krim gründen Mariupol am Asowschen Meer", "4e3af209"], "d": ["Griechen von der Krim gründeten Mariupol an der Stelle, wo die Kalmius in das Asowsche Meer mündet. Die Stadt wurde 1784 Kreisstadt im Gouvernement Jekaterinoslaw.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Jekaterinoslaw an seinen heutigen Standort am Dnjepr verlegt", "ec361381"], "d": ["Jekaterinoslaw, das Potemkin 1778 an der Mündung der Flüsse Kilčen und Samara gegründet hatte, wurde 1783 wegen seiner ungesunden Lage an den heutigen Standort verlegt.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Der russische Flottenhafen Sewastopol in der Bucht von Achtiar gegründet", "01058a25"], "d": ["Nach der Annexion der Krim durch Russland 1783 wurde die Bucht, in der das krimtatarische Dorf Achtiar (Akyar) lag, für einen Militärhafen ausgewählt; der Hafen wurde im folgenden Jahr gegründet und erhielt den Namen Sewastopol. Die Stadt wurde 1804 Haupthafen der russischen Schwarzmeerflotte.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Befestigung Nikolajew an der Bug-Mündung gegründet", "d57e52b9"], "d": ["An der Stelle, wo der Südliche Bug und der Inguł zusammenfließen, wurde auf Befehl von Fürst Potemkin eine Befestigung angelegt. 1788 wurde dort eine Werft eröffnet, und die Siedlung wurde eines der Schiffbauzentren der Schwarzmeerflotte.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Grenzsiedlung am Molotschna, Kern von Melitopol, gegründet", "637d5817"], "d": ["Nach der Annexion der Krim wurde am Ufer des Flusses Molotschna eine Grenzsiedlung gegründet. Die Siedlung erhielt 1816 den Namen Nowoolexandriwka und wurde 1841 unter dem Namen Melitopol zur Stadt gemacht.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Nowotscherkassk, der neue Mittelpunkt des Donkosakenheeres, gegründet", "bf5709fd"], "d": ["Der Verwaltungssitz des Donkosakenheeres ging von Tscherkassk, das bis dahin Zentrum gewesen war, auf das am Ort Birjutschij Kut zwischen den Flüssen Aksai und Tusłow gegründete Nowotscherkassk über.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Wadi Halfa wird auf der Nubienreise Burckhardts verzeichnet", "6efc72ec"], "d": ["Der Schweizer Reisende J. L. Burckhardt schreibt in seinem Tagebuch vom 6. März 1813, dass er durch Wadi Halfa gekommen sei und dort ein wenig Handel getrieben werde. Es ist der erste auffindbare datierte Beleg.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Anlegestelle Berdjansk am Asowschen Meer gegründet", "908ac3cf"], "d": ["Auf Initiative von Fürst Michail Woronzow wurde Berdjansk an der Stelle gegründet, wo die Berda in das Asowsche Meer mündet. Die Siedlung wurde 1835 Stadt und 1842 Kreisstadt.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Die Bewohner Malatyas bleiben in den Weingärten von Aspuzu – der Kern des modernen Malatya", "d1dba159"], "d": ["Das osmanische Hauptquartier gegen die ägyptische Armee İbrahim Paschas wurde im Sommer 1838 von Mezraa nach Malatya verlegt. Die Malatyaer, die in ihren Sommerhäusern in Aspuzu wohnten, kehrten nach dem Abzug der Armee nicht in ihre Winterhäuser in der verfallenen Altstadt zurück; Aspuzu wurde der Kern des modernen Malatya. Das alte Malatya (Battalgazi) bestand verkleinert fort.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Van wird an neuem Ort gegründet – die zerstörte Altstadt wird aufgegeben", "6d278578"], "d": ["Van wurde am 2. April 1918 von der Besetzung befreit. Die Zurückkehrenden bauten das in den Kriegsjahren zerstörte alte Van am Seeufer nicht wieder auf, sondern gründeten etwa 7 km vom Ufer landeinwärts an der Stelle der alten Viertel Norşen und Arak eine neue Stadt. Die Altstadt wurde aufgegeben.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Maraş kommt an die Mamluken — der Statthalter von Aleppo, Bilbân et-Tabahî, nimmt es den Armeniern ab", "03171265"], "d": ["Maraş, das seit 1258 in der Hand des Königreichs Kilikisch-Armenien gewesen war, war 1293 durch den Vertrag Sultan Halils mit den Armeniern kurzzeitig an die Mamluken gekommen und nach deren Abzug wieder in armenische Hand gefallen. Im Jahr 697 (1298) nahm der mamlukische Statthalter von Aleppo, Bilbân et-Tabahî, die Stadt zurück. Maraş blieb danach bis zum Aufstieg der Dulkadır mamlukisches Gebiet.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Das Byzantinische Reich wird tributpflichtig gegenüber den Osmanen", "615df998"], "d": ["Nach dem Sieg von Çirmen (1371) erklärte sich der byzantinische Kaiser Ioannes V. im Winter 1372 bereit, Tributpflichtiger Murads I. zu werden: Er würde jährlich Tribut zahlen und für die Feldzüge des Sultans Soldaten stellen. Byzanz blieb von diesem Datum bis 1403 ein den Osmanen unterstehender Vasallenstaat; die Blockade Bayezids des Blitzes 1391 erhöhte den Tribut. Nach der Niederlage von Ankara befreite der Vertrag von Gallipoli mit Süleyman Çelebi (1403) Byzanz vom Tribut; durch den Vertrag mit Murad II. im Jahr 1424 begann der Tribut erneut.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Bayezid der Blitz gliedert nach dem Tod Barkuks Besni, Darende und Divriği dem osmanischen Gebiet an", "8e57d7e6"], "d": ["Nachdem die Verwaltung des Mamlukenstaates nach dem Tod des mamlukischen Sultans Barkuk (Juni 1399) in Unordnung geraten war, zog Bayezid der Blitz in das Euphratbecken hinab und gliederte zusammen mit Malatya auch Besni (Behisni), Darende und Divriği dem osmanischen Gebiet an. Sivas war zuvor nach dem Tod Kadı Burhâneddins im Sommer 1398 den Osmanen überlassen worden. Divriği stand seit 1391 unter mamlukischer Herrschaft und war ein vorgeschobener Posten der Provinz Aleppo. Die osmanische Verwaltung hielt sich hier nicht lange: Wegen der nahenden Gefahr durch Timur wurde Divriği 1401 den Mamluken wieder übergeben; die endgültige Eingliederung der Stadt unter osmanische Verwaltung erfolgte nach Mercidâbık 1516.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni fällt während Timurs Feldzug gegen Sivas und Malatya an die Mamluken", "4853da9a"], "d": ["Besni, das Bayezid der Blitz 1398 zusammen mit Sivas, Darende und Malatya genommen hatte, fiel 1400, als Timur Sivas und Malatya einnahm, in die Hand der Mamluken. Timur eroberte am 27. September 1400 nach einer heftigen Belagerung auch Besni; nach seinem Abzug aus der Region kam Besni wieder unter mamlukische Herrschaft und blieb bis zum August 1516, als Sultan Selim der Gestrenge es einnahm, mamlukisch (abgesehen von einer dulkadirischen Zwischenzeit).", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği wird wegen der Gefahr durch Timur wieder den Mamluken übergeben", "97196b1f"], "d": ["Divriği, das Bayezid der Blitz 1398 den Mamluken abgenommen hatte, wurde 1401 beim Herannahen Timurs an Anatolien den Mamluken wieder überlassen. Deshalb erscheint Divriği nach der Zerstörung von Sivas durch Timur (1400) auf der Karte in mamlukischer Farbe; in denselben Monaten nahm Bayezid im Osten Erzincan und Kemah ein, das heißt, mamlukisches Gebiet blieb zwischen den osmanischen Gebieten im Westen (Sivas) und im Nordosten (Kemah) liegen. Divriği ging erst nach Mercidâbık 1516 endgültig an die Osmanen über.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Der Mamlukensultan Şeyh nimmt Antep und Darende den Dulkadır zurück", "f90c9508"], "d": ["Beunruhigt über die Freundschaft der Dulkadır mit den Osmanen, zog der Mamlukensultan Şeyh 1414 zu Felde; er nahm Antep und Darende zurück, die er den Dulkadır zuvor aus freien Stücken überlassen hatte.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadıroğlu Mehmed Bey nimmt Darende zurück und gliedert Besni seinem Gebiet an", "df914dcb"], "d": ["Darende, das die Mamluken 1414 genommen hatten, nahm Dulkadıroğlu Mehmed Bey 1418 zurück und gliederte auch Besni seinem Gebiet an.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Die Mamluken besiegen die Dulkadır bei Antep; Besni kehrt unter mamlukische Verwaltung zurück (ungefähr)", "72742430"], "d": ["Das mamlukische Heer besiegte 1436 bei Antep die Dulkadır, Mehmed Bey zog sich nach Akdağ zurück. Das Jahr der Rückkehr Besnis zu den Mamluken ist in der Quelle nicht verzeichnet; Besni war 1418 den Dulkadır angegliedert worden und musste vor seiner Wegnahme von den Mamluken durch Şehsuvar Bey im Jahr 1465 zu den Mamluken zurückgekehrt sein. Der Atlas gibt Besni zusammen mit dieser Niederlage beim benachbarten Zentrum Antep (erklärte Annäherung) den Mamluken zurück.", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadıroğlu Şehsuvar Bey nimmt Besni den Mamluken ab (ungefähr)", "843f0fc4"], "d": ["Şehsuvar Bey (1465-1472), von Mehmed dem Eroberer zum Bey der Dulkadır ernannt, eroberte Besni, Gerger, Birecik und Rumkale, die in mamlukischer Hand waren; die Mamluken wurden im Herbst 1467 am Turna-Gebirge und im Frühjahr 1468 in der Nähe von Antep besiegt.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emir Yeşbek besiegt Şehsuvar Bey; Besni kehrt unter mamlukische Verwaltung zurück (ungefähr)", "4d856aee"], "d": ["Im Frühjahr 1471 besiegte Emir Yeşbek Şehsuvar Bey am Savron-Bach; die Mamluken nahmen Kadirli und Kozan zurück. Şehsuvar wurde 1472 in Kairo hingerichtet, die Mamluken setzten Şahbudak wieder als Bey ein. Mit dieser Rückkehr kam auch Besni unter mamlukische Verwaltung (TDV besni: „gegen Ende des 15. Jahrhunderts fiel es wieder in die Hände der Mamluken“).", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Ferdinands Truppen besetzen und befestigen Szolnok", "6c8416e6"], "d": ["Als die Osmanen sich anschickten, in Szolnok an der Theiß eine Festung zu errichten, kamen die Truppen Ferdinands I. ihnen zuvor: Mitte September 1550 besetzten sie Szolnok, und die Festung wurde Mitte Oktober verteidigungsfähig gemacht. So fiel Szolnok, das zum Land Isabellas gehörte, ein Jahr vor dem Übergang Siebenbürgens an Ferdinand in habsburgische Hand; die Osmanen nahmen die Festung 1552 ein.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Siebenbürgen kommt unter habsburgische Verwaltung: Der Landtag von Kolozsvár erkennt den Verzicht Isabellas an", "8458a566"], "d": ["Nach der Übereinkunft Martinuzzis mit Ferdinand unterzeichnete Königin Isabella im Namen des minderjährigen Königs János Zsigmond am 19. Juni 1551 auf der Burg Szászsebes den ihr aufgezwungenen Verzichtsakt. Der am 26. Juli in Kolozsvár zusammengetretene siebenbürgische Landtag erkannte diesen Verzicht und die Herrschaft König Ferdinands an; das habsburgische Heer von General Castaldo zog in Siebenbürgisch Weißenburg (Gyulafehérvár) ein. So kam das den Osmanen unterstehende Siebenbürgen unter eine fünf Jahre währende habsburgische Verwaltung.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Die habsburgische Verwaltung in Siebenbürgen endet: Siebenbürgen wird wieder ein den Osmanen unterstehendes Woiwodat", "721a482a"], "d": ["Da János Zsigmond minderjährig war, versuchten die Habsburger 1551 durch den ihm als Vormund bestellten Priester kroatischer Herkunft Martinuzzi (Fráter György), Siebenbürgen zu beherrschen; Siebenbürgisch Weißenburg (Gyulafehérvár), Klausenburg, Kronstadt und Schäßburg blieben fünf Jahre unter habsburgischer Verwaltung. Die Osmanen verhinderten diesen Zustand, und Siebenbürgen wurde wieder ein ihnen unterstehendes tributpflichtiges Woiwodat. Siebenbürgen bewahrte danach im 16. und 17. Jahrhundert etwa 150 Jahre lang seinen Status, der auf weitgehender Autonomie in inneren Angelegenheiten und Bindung an Istanbul in äußeren Angelegenheiten beruhte.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt und Tokaj gehen auf die Seite Szapolyais über", "587c782d"], "d": ["Nach der Rückkehr Isabellas und János Zsigmonds nach Siebenbürgen im Jahr 1556 belagerten die Anhänger Szapolyais 1556 Nagyvárad. 1557 eroberten die Aristokraten der oberen Theiß die wichtigsten königlichen Festungen — Várad, Huszt und Tokaj; in Ferdinands Hand blieben nur Gyula und Világos. Várad wurde danach die Festung des Fürstentums Siebenbürgen und blieb dies bis zur Einnahme durch die Osmanen im Jahr 1660.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi nimmt Szatmár ein — das nördliche Ende Siebenbürgens fällt an die Habsburger", "2256bb27"], "d": ["Szatmár, das 1561 durch den Seitenwechsel Menyhért Balassas an die Habsburger gefallen war, hatte István Báthory im Herbst 1564 durch einen Überfall zurückgewonnen und Siebenbürgen angegliedert. Der habsburgische Befehlshaber Lazarus von Schwendi ging im Februar 1565 zum Gegenangriff über: Tokaj fiel am 9. Februar, Szerencs vier Tage später, und Szatmár geriet fast widerstandslos in die Hand der kaiserlichen Truppen.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Bocskais Truppen nehmen Szatmár ein", "e93b098b"], "d": ["Während sich der Bocskai-Aufstand auf den Nordosten Ungarns ausbreitete, nahm Gyulaffy das von ihm belagerte Szatmár am 21. Januar 1605 ein. Der Wiener Friede vom 23. Juni 1606 überließ das Komitat Szatmár Bocskai auf Lebenszeit; da kein männlicher Erbe vorhanden war, fiel das Komitat mit Bocskais Tod am 29. Dezember 1606 an das Königreich zurück.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Tod István Bocskais — das Komitat Szatmár fällt an das Königreich zurück", "3721bb9b"], "d": ["Der siebenbürgische Fürst István Bocskai starb am 29. Dezember 1606 in Kassa. Der Wiener Friede (23. Juni 1606) hatte ihm die Komitate einschließlich Szatmárs auf Lebenszeit überlassen, mit Rückfall an das Königreich im Fall fehlender männlicher Erben; gemäß dieser Bestimmung ging das Komitat Szatmár an das habsburgische ungarische Königreich zurück. Siebenbürgen begann die Suche nach einem neuen Fürsten.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Bethlen Gábor nimmt das Komitat Szatmár unter seine Kontrolle", "80263da1"], "d": ["Durch den Ungarn-Feldzug Bethlen Gábors im Herbst 1619 kam das Komitat Szatmár unter die Kontrolle des siebenbürgischen Fürsten; im November 1619 wandte er sich brieflich an das Komitat. Der Vorvertrag vom 23. Januar 1620 und der Friede von Nikolsburg überließen Bethlen die sieben Komitate einschließlich Szatmárs auf Lebenszeit. Nach Bethlens Tod (15. November 1629) wurde die Rückgabe der Komitate an das Königreich am 30. März 1630 abgeschlossen.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Die Rückgabe der sieben Komitate Bethlen Gábors an das Königreich ist abgeschlossen", "31b5968f"], "d": ["Der Friede von Nikolsburg hatte Bethlen Gábor sieben oberungarische Komitate einschließlich Szatmárs auf Lebenszeit überlassen. Nach Bethlens Tod am 15. November 1629 begann die Rückgabe der Komitate an das Königreich mit der Weisung vom 30. November 1629 und wurde am 30. März 1630 abgeschlossen.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["György I. Rákóczi übernimmt Szatmár", "f398635b"], "d": ["Beim Feldzug des siebenbürgischen Fürsten György I. Rákóczi im Jahr 1644 trat die deutsche Garnison von Szatmár in Rákóczis Dienst, und die Festung kam in siebenbürgische Hand. Der Friede von Linz vom 16. Dezember 1645 überließ die Festung den Erben Rákóczis, solange ein Rákóczi auf dem siebenbürgischen Thron säße.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Der Verlust von Nitra — De Souches nimmt die Festung zurück", "c71bf012"], "d": ["Nitra, das sich nach der Eroberung von Neuhäusel (Uyvar) 1663 nach kurzem Widerstand ergeben hatte, wurde vom kaiserlichen Befehlshaber De Souches am 15. April 1664 belagert; die Festung ergab sich am 3. Mai 1664. Da der Friede von Vasvár die eroberten Orte im bestehenden Zustand beließ, blieb Neuhäusel (Uyvar) osmanisch, während Nitra in habsburgischer Hand blieb.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Der Verlust von Léva", "f311920e"], "d": ["De Souches belagerte nach Nitra am 9. Juni 1664 Léva; am 13. Juni wurde die Kapitulation unterzeichnet, und die Festung war am 14. Juni in der Hand der kaiserlichen Truppen. Die Schlacht bei Léva (Garamszentbenedek) am 19. Juli 1664 änderte nichts am Besitzstand; sie endete damit, dass die Habsburger Léva und Nitra behielten.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroschenko übergibt Tschyhyryn an Samojlowytsch", "3b538237"], "d": ["Der unter osmanischem Schutz stehende Hetman des rechten Ufers, Petro Doroschenko, übergab seine Hauptstadt Tschyhyryn am 19. September 1676 dem Hetman des linken Ufers, Samojlowytsch, und den russischen Truppen. Die Osmanen setzten Doroschenko ab und ernannten Juri Chmelnyzkyj an seiner Stelle; die Belagerung von 1677 zur Vertreibung der russischen Garnison aus Tschyhyryn schlug fehl, die Festung wurde erst am 21. August 1678 genommen.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Übergabe der Banater Festungen Siebenbürgens (Temeswar, Lippa, Lugoj, Karánsebes) an den König von Ungarn, Ferdinand", "0e354976"], "d": ["1551 zog das habsburgische Heer unter General Castaldo in Siebenbürgen ein; Königin Isabella und ihr Sohn mussten auf ihre Rechte auf den ungarischen Thron verzichten. Martinuzzi schickte mit Zustimmung Castaldos Mitte Juli 1551 Endre Báthory, um die Festungen Temeswar, Lippa, Solymos, Karánsebes, Lugoj, Becse, Becskerek und Csanád im Namen Ferdinands zu übernehmen. Die südlichen Festungen des den Osmanen unterstehenden Siebenbürgen fielen so in habsburgische Hand; die Feldzüge des Gesetzgebers von 1551-1552 sind die Antwort darauf.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Péter Petrovics wird zum Sandschakbey von Lugoj und Karánsebes ernannt", "bcbe73e4"], "d": ["Auf die eindringliche Bitte Isabellas und Petrovics' beschloss der Gesetzgeber, den minderjährigen János Zsigmond nach Siebenbürgen zurückzuführen. In seinem am 7. April 1554 aus Aleppo geschriebenen Brief befahl er Siebenbürgen, das Kind in sein Land zurückzubringen; er wies auch die Woiwoden der Walachei und der Moldau an, hierbei Petrovics zu helfen, den er zur selben Zeit zum Sandschakbey von Lugoj und Karánsebes ernannt hatte. Das 1552 eroberte Lugoj wurde so als osmanischer Sandschak Petrovics übergeben.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Aufhebung der Belagerung von Lippa — der Überfall des Banus von Lugoj auf Temeswar", "be03430e"], "d": ["Im Frühjahr 1596 belagerte der Pascha von Temeswar Lippa. In der Nacht vom 10. auf den 11. Mai überfielen auf Befehl des siebenbürgischen Banus von Lugoj, György Palatics, die Soldaten György Budays die Vorstädte Temeswars und steckten sie in Brand; dass György Borbély in der Festung alle Kanonen abfeuern ließ, brachte den Pascha ebenfalls zu dem Glauben, es sei Hilfe gekommen. Der Pascha zog am 11. Mai von Lippa ab und eilte, sein Zentrum zu schützen. Lugoj stand zu dieser Zeit in der Hand des Fürstentums Siebenbürgen.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Die Besetzung von Orșova durch die österreichischen Truppen unter Veterani", "1b4a4f6c"], "d": ["Im Feldzug von 1688 marschierte General Veterani nach der Einnahme von Karánsebes auf Orșova und besetzte auch dieses. Die Quelle nennt keinen Tag der Besetzung; die Jahresbasis, der 1. Januar 1688, wurde verwendet.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Die Rückeroberung von Orșova durch Thököly und die osmanischen Truppen", "c5645da9"], "d": ["Nach der Einnahme von Vetislan marschierten Thököly und die osmanischen Paschas auf Orșova, das Veterani 1688 besetzt hatte. Nach unbedeutenden Gefechten zog Thököly am 15. Juli 1689 in Orșova ein. Heissler, der auf die Nachricht von der Gefahr gekommen war, sah, dass die gegenüberstehende Streitmacht an Munition und Schiffen gut ausgerüstet war, und zog sich zum Schutz Siebenbürgens zurück. Auch der Angriff Herbevilles vor der Stadt im August konnte Orșova nicht zurückgewinnen.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Der Sandschak Lugoj gerät unter habsburgische Besetzung (1691-1695)", "c8bcd6bd"], "d": ["Der Sandschak Lugoj blieb von 1691 bis 1695 unter habsburgischer (deutscher) Besetzung; Mustafa II. eroberte ihn am 22. September 1695 zurück. Im alten Eintrag war der Zeitraum 1689-1695 eine erklärte Lücke; der Abschnitt 1691-1695 wird nun als habsburgisch gefärbt, 1689-1691 bleibt eine Lücke. Das Datum ist nur als Jahr übernommen.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Die Festung Lugos kam unter habsburgische Verwaltung", "6a9d401f"], "d": ["Die zum Eyalet Temeswar gehörende Sandschak-Festung Lugoj war seit 1695 in osmanischer Hand; mit der Übergabe des Eyalet-Zentrums nach der Belagerung von 1716 wurde sie der Habsburgermonarchie überlassen. Der frühere Eintrag setzte den Wechsel auf die Jahresuntergrenze, den 1. Januar 1716.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Die Einnahme von Orșova durch das habsburgische Heer (Feldzug von 1717)", "7a4faffe"], "d": ["Im Feldzug von 1717 erreichte General Splényi am 27. August Orșova und nahm die Stadt mühelos ein; Orșova, das Mercy 1716 nicht hatte einnehmen können, fiel so in habsburgische Hand. Da die Waben am Donauufer in der Umgebung (einschließlich des Abschnitts Đerdap auf der serbischen Seite) dem nächstgelegenen Siedlungspunkt Orșova angehören, werden sie mit dessen Besitzer gefärbt. Das Datum ist nur als Jahr übernommen; der genaue Tag ist unbestätigt.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Der Übergang der Palanka Orșova an die Osmanen — der Wachtkommandant zieht sich nach Ada Kale zurück", "de759b16"], "d": ["Bei der Eröffnung des Feldzugs von 1738 griff der Wachtkommandant von Vidin, Hacı Mehmed Pascha, die Schanze Erzsébet an der Donau an. Am Nachmittag des 8. Mai marschierte eine Sipahi-Abteilung von 4-5 Tausend Mann am linken Donauufer nach Orșova und griff die Palanka Orșova an; der österreichische Kommandant, der etwa hundert Mann verlor, zog sich nach Neu-Orșova, das heißt auf die Inselfestung Ada Kale, zurück. Nach den Gefechten bei Mehadia im Juli fiel auch Ada Kale im August 1738 in osmanische Hand; der Frieden von Belgrad 1739 erkannte den Zustand an.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II. nimmt Alacahisar ein, Niš und Pirot kehren zu den Osmanen zurück", "54af926a"], "d": ["Nach dem erbenlosen Tod des serbischen Despoten Stefan Lazarević (1427) erhob Murad II. unter Berufung auf die Ehe Bayezids des Blitzes mit einer serbischen Prinzessin den Anspruch, rechtmäßiger Erbe Serbiens zu sein, setzte sich in Bewegung und nahm Alacahisar ein (1428). Im selben Jahr nahmen die Osmanen nach Lazarevićs Tod auch die Festung Pirot zurück — die Stadt war 1412 von Stefan genommen und gegen Mûsâ Çelebi verteidigt worden. Nach dem TDV-Artikel nis nahmen die Osmanen im selben Jahr (831/1428) auch Niš zurück. So kam die Linie, die die Täler der Großen Morava und der Nišava verband, unter osmanische Kontrolle.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Das Kreuzfahrerheer erobert Pirot — der Nišava-Arm des „Langen Feldzugs“", "fdf6140c"], "d": ["Das Kreuzfahrerheer unter König Vladislav und dem serbischen Despoten Đurađ Branković eroberte 1443 Pirot. In der Fortsetzung desselben Feldzugs sollten die osmanischen Truppen im November am Pass von İzladi eine Niederlage erleiden. Pirot war nach dem Vertrag von Szeged (1444) von Murad II. wieder den Serben gegeben worden, ging aber nach dem Tod Đurađ Brankovićs 1456 an die Osmanen über.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Im Gebiet von Alacahisar wird die endgültige osmanische Herrschaft hergestellt", "9715382a"], "d": ["Alacahisar, das durch den Vertrag mit den ungarischen Delegierten 1444 Branković überlassen worden war, kam in den Jahren nach dem Sieg von Varna wieder unter türkische Herrschaft. Diese zweite Eroberung der Stadt ist nicht durch einen Kriegsbericht, sondern durch einen Finanzeintrag belegt: Die Timar-Einträge einiger zu Alacahisar gehörender Dörfer sind auf Ende 1453/Anfang 1454 datiert; dies ist jedoch nur ein Dorfzeugnis — 1454 wurden die osmanischen Truppen in der Umgebung von Alacahisar geschlagen, und 1455 wurde Alacahisar als Grenzpunkt Branković überlassen. Nach dem TDV wurde die endgültige osmanische Herrschaft in der Region 1458 hergestellt.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Die Gründung des Despotats Morea — Manuel Kantakuzenos in Mistras", "87660b82"], "d": ["Der byzantinische Kaiser Ioannes Kantakuzenos gab seinem Sohn Manuel in der Morea einen eigenen Verwaltungsbezirk; so entstand das Despotat Morea mit dem Zentrum Mistras. Manuel regierte bis 1380; in dieser Zeit blühten byzantinische Kultur und Kunst besonders in Mistras. Das Despotat bestand bis zur Eroberung durch Mehmed den Eroberer im Jahr 1460.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despot Konstantinos nimmt Patras den Franken ab", "cb0dd18c"], "d": ["Konstantinos, der Despot der Morea (1449 der letzte byzantinische Kaiser), nahm Patras den Lateinern wieder ab; so wurde auch dieser bedeutende Hafen im Nordwesten der Halbinsel dem Despotat angegliedert. Patras kam 1458 beim Morea-Feldzug Mehmeds des Eroberers unter osmanische Herrschaft.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača „Herzog von St. Sava“ — die Geburt der Herzegowina", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, der Hum und Trebinje in einem Fürstentum vereinigte, erhob sich gegen den König von Bosnien und erklärte sich zum „Herzog (Herceg) von St. Sava“; den Titel verlieh ihm 1448 Kaiser Friedrich III. Der Name Herzegowina („Land des Herzogs“) stammt von diesem Titel. Die Herzegowina ging ab 1466 Stück für Stück an die Osmanen über, wurde 1470 Sandschak; die restlichen Gebiete wurden Anfang 1482 angegliedert.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Frieden von Krakau — der Deutschordensstaat wird zum Herzogtum Preußen", "78666ddd"], "d": ["Albrecht von Brandenburg, der Hochmeister des Deutschen Ordens, unterzeichnete, da er gegen Polen keine Hilfe fand, den Frieden von Krakau. Der Ordensstaat wurde unter der Lehnshoheit Polens ein erbliches und weltliches Herzogtum, das an das Haus Brandenburg überging. Das Zentrum war Königsberg; Albrecht gründete dort 1544 die Albertus-Universität. Das Herzogtum wurde 1701 zum Königreich Preußen.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Ausrufung der Republik Österreich — Ende der Habsburgermonarchie", "c84f316c"], "d": ["Am Tag nach dem Rückzug Kaiser Karls I. von den Staatsgeschäften am 11. November nahm die Provisorische Nationalversammlung das Gesetz über die Staats- und Regierungsform an, und die Republik wurde ausgerufen. An die Stelle des habsburgischen Österreich trat die Erste Republik mit Sitz in Wien. Mit dieser Erklärung wurden Wien, Linz, Salzburg, Innsbruck, Klagenfurt, Bregenz und die übrigen deutschösterreichischen Städte Gebiet der Republik Österreich (Deutschösterreich).", "2dcc1399"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Batumi unter der Herrschaft des Königreichs/der Königreiche Georgien — datiertes Zeugnis der Quelle", "62cd2833"], "d": ["Die Quelle zeigt die Stadt Batumi zu diesem Datum unter der Verwaltung des Königreichs/der Königreiche Georgien; die frühere Zugehörigkeit ist in der Quelle nicht datiert (der Atlas lässt die Zeit vor diesem Datum leer).", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["Der Marwanide Nasrüddevle fügte Âmid seinem Emirat hinzu", "9fbc8c85"], "d": ["Der marwanidische Emir Nasrüddevle Ahmed fügte Âmid (Diyarbekir) den Gebieten des Emirats hinzu; im folgenden Jahr nahm er auch Urfa.", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Merâga kam unter seldschukische Herrschaft", "c011cac9"], "d": ["Merâga, in der Hand der Revvâdîler, kam durch den Aserbaidschan-Feldzug Tuğrul Beys unter seldschukische Herrschaft.", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Tuğrul Bey zog in Bagdad ein", "38af55c2"], "d": ["Tuğrul Bey, der auf Einladung des Kalifen Kāim-Biemrillâh nach Bagdad kam, beendete die Herrschaft der Buyiden.", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Mosul fiel an die Seldschuken", "20b8da93"], "d": ["Mosul fiel zusammen mit dem Irak an die Seldschuken; trotz der kurzen Besetzung durch Besâsîrî blieb es vier Jahre in seldschukischer Hand.", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Mosul wieder bei den Ukaylî", "8b7c0603"], "d": ["Mosul kam 1061 erneut unter die Herrschaft der Ukaylî; auch nach der seldschukischen Einnahme von 1084 gab Melikşah die Stadt dem Ukaylî-Emir zurück.", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Alparslan beendete das Schahtum von Nachitschewan", "5620360e"], "d": ["Alparslan, der die Revvâdîler besiegt hatte, beseitigte das von den Dülefî gegründete Schahtum von Nachitschewan.", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["Emir Saltuk eroberte Erzurum", "f52c09dd"], "d": ["Nach Manzikert verlieh Alparslan die Umgebung von Erzurum als Iqta an Emir Saltuk; Saltuk nahm die Stadt im selben Jahr, und das Saltuklu-Beylik wurde gegründet (nach Yinanç 1080).", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Dânişmend Gazi eroberte Sivas", "348d7ad3"], "d": ["Dânişmend Gazi, der das ihm nach Manzikert als Iqta verliehene Sivas nahm, gründete dort den Kern der Dynastie (das Eroberungsdatum ist umstritten; es gibt auch die Überlieferung von 1080).", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Philaretos nahm Malatya ein", "9c80e3bd"], "d": ["Philaretos, der in Kilikien ein armenisches Fürstentum gegründet hatte, nahm Malatya, indem er sich als Vertreter von Byzanz ausgab, und verwaltete es durch Statthalter (Gabriel u. a.).", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["Emir Dânişmend eroberte Tokat", "c9321fb6"], "d": ["Nach dem Sieg von Manzikert nahm Emir Dânişmend Tokat von Byzanz.", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["Die Seldschuken nahmen Hasankeyf von den Marwaniden", "4fa9d559"], "d": ["Zur Zeit Melikşahs beendeten die Seldschuken die marwanidische Herrschaft und nahmen auch Hasankeyf.", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["Der Sohn Fahrüddevles nahm Âmid, die marwanidische Herrschaft endete", "ecaf6b03"], "d": ["Zaîmürrüesâ, der Sohn des von Melikşah beauftragten Fahrüddevle İbn Cehîr, nahm Âmid von den Marwaniden.", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Tutuş nahm Diyarbekir", "469b8ebc"], "d": ["Tutuş, der nach dem Tod Melikşahs Anspruch auf das Sultanat erhob, nahm die Region Diyarbekir und nahm den letzten marwanidischen Emir Mansûr gefangen.", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["Der turkmenische Bey Sadr begann in Âmid zu herrschen", "3d67b786"], "d": ["Nach dem Tod Tutuş' wurde der turkmenische Bey Sadr Herrscher von Âmid; sein Nachfolger İnal gründete die Dynastie der İnaloğulları.", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Kürboğa nahm Mosul", "462a238f"], "d": ["Der seldschukische Emir Kürboğa nahm Mosul von den Ukaylî. (Dhū l-Qaʿda 489 / November 1096; der Atlas schreibt in Anpassung an den Eintrag mit Jahrespräzision.)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Niksar unter der Herrschaft der Danischmendiden — datiertes Zeugnis der Quelle", "81181870"], "d": ["Die Quelle zeigt die Stadt Niksar zu diesem Datum unter der Verwaltung der Danischmendiden; die frühere Zugehörigkeit ist in der Quelle nicht datiert (der Atlas lässt die Zeit vor diesem Datum leer).", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["Der Danischmendide Gümüştegin Gazi nahm Malatya", "87f1166c"], "d": ["Gümüştegin Gazi eroberte Malatya nach einer Belagerung.", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Kılıcarslan I. übernahm Malatya", "eca366d5"], "d": ["Nach dem Tod Gümüştegins fügte Kılıcarslan I. Malatya nach einer Belagerung von über zwei Monaten dem seldschukischen Gebiet hinzu.", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["Der Mezyedî Sadaka starb bei Nu'maniye, Hille fiel an die Seldschuken", "e5ecea7c"], "d": ["Muhammed Tapar besiegte Sadaka; sein Sohn Dübeys geriet in Gefangenschaft, und ihm wurde die Rückkehr nach Hille nicht erlaubt.", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["İlarslan eroberte Elbistan von Tancred zurück", "923962c2"], "d": ["İlarslan, der Atabeg des Königs von Malatya Tuğrul Arslan, eroberte das vom Fürsten von Antiochia, Tancred, genommene Elbistan zurück.", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["Der Artukide Belek wurde Herrscher von Harput", "83425a6e"], "d": ["Belek b. Behrâm, ein Enkel Artuk Beys, wurde Herrscher von Harput und gründete sein Beylik mit Zentrum Palu.", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Niğde unter der Herrschaft des Anatolischen (Türkischen) Seldschukenstaates — datiertes Zeugnis der Quelle", "dfb24c4b"], "d": ["Die Quelle zeigt die Stadt Niğde zu diesem Datum unter der Verwaltung des Anatolischen (Türkischen) Seldschukenstaates; die frühere Zugehörigkeit ist in der Quelle nicht datiert (der Atlas lässt die Zeit vor diesem Datum leer).", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Dübeys kehrte nach Hille zurück", "9bc0e03a"], "d": ["Nach dem Tod Muhammed Tapars konnte Dübeys zur Zeit des irakisch-seldschukischen Sultans Mahmud nach Hille gehen.", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Mahmud wurde in Bagdad zum irakisch-seldschukischen Sultan ausgerufen — der irakisch-seldschukische Staat wurde gegründet", "18babf94"], "d": ["Nach dem Tod Muhammed Tapars wurde sein Sohn Mahmud vom Kalifen zum Sultan ausgerufen; der irakisch-seldschukische Staat wurde gegründet. Bagdad sowie Mosul und Tikrit blieben dem irakisch-seldschukischen Sultanat unterstellt, auch Aserbaidschan (Merâga, Nachitschewan) fiel an den irakisch-seldschukischen Anteil. Tikrit erscheint in der Quelle in diesem Jahr als Iqta der Schahne von Bagdad.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["Ioannes II. Komnenos eroberte Denizli zurück", "cb523c0f"], "d": ["Der byzantinische Kaiser Ioannes II. Komnenos zwang den seldschukischen Kommandanten Alp Kara in Laodikeia zum Abzug; das Gebiet von Denizli fiel wieder an Byzanz (der Byzanz-Eintrag nennt 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Aksungur el-Ahmedîlî wurde nach Merâga entsandt", "7a3d6deb"], "d": ["Sultan Mahmud entsandte Aksungur el-Ahmedîlî nach Merâga; das Atabegtum der Ahmedîlî ließ sich in der Stadt nieder.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-12-10:0":{"b": ["Der danischmendidische Emir Ghazi übernahm Malatya; auch Elbistan ging an die Danischmendiden", "97f3f958"], "d": ["Nach dem Tod Beleks nahm Emir Ghazi nach langer Belagerung Malatya dem seldschukischen Fürsten Tughrul Arslan ab; mit der Einnahme des Gebiets von Malatya kam auch Elbistan unter danischmendidische Verwaltung.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["Emîr Gazi nahm Ankara von den Seldschuken", "25b745cd"], "d": ["Der Danischmendide Emîr Gazi besiegte Melik Arab, den Sohn Kılıcarslans I., und nahm ihm Ankara ab.", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["İmâdüddin Zengî Atabeg von Mosul (Zengiden)", "ba79276b"], "d": ["Der irakisch-seldschukische Sultan Mahmud verlieh Mosul als Iqta an İmâdüddin Zengî; das Atabegtum von Mosul wurde gegründet.", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Kayseri unter der Herrschaft der Danischmendiden — datiertes Zeugnis der Quelle", "3b9b8604"], "d": ["Die Quelle zeigt die Stadt Kayseri zu diesem Datum unter der Verwaltung der Danischmendiden; die frühere Zugehörigkeit ist in der Quelle nicht datiert (der Atlas lässt die Zeit vor diesem Datum leer).", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Kemah unter der Herrschaft der Mengücüklüler (Mengücekoğulları) — datiertes Zeugnis der Quelle", "d86927c6"], "d": ["Die Quelle zeigt die Stadt Kemah zu diesem Datum unter der Verwaltung der Mengücüklüler (Mengücekoğulları); die frühere Zugehörigkeit ist in der Quelle nicht datiert (der Atlas lässt die Zeit vor diesem Datum leer).", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["Sultan Mesud nahm Elbistan", "825e2c56"], "d": ["Mesud I. nahm Elbistan und Ceyhan, die in der Hand Aynüddevles waren, und ernannte seinen Sohn Kılıcarslan zum Melik.", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Nachitschewan wurde den İldenizliler angeschlossen", "774400cc"], "d": ["Mit dem Zerfall der Seldschuken wurde Nachitschewan dem Staat der İldenizliler angeschlossen und war bis 1174 deren Zentrum (das Jahr des Anschlusses ist ohne Jahresangabe; Beginn der Dynastie).", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Tikrit geht an die Begteginliler über (EI2)", "a2caf5af"], "d": ["Nach TDV, die darin EI2 wiedergibt, stand Tikrit von 1149 bis 1190 unter der Herrschaft der Begteginliler.", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-04-30:0":{"b": ["Sultan Mas'ud übergab Hilla an Salarkird", "4bdbd034"], "d": ["Nach dem Tod des Mazyadiden Ali übergab Sultan Mas'ud Hilla an seinen Befehlshaber Salarkird.", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-04-08:0":{"b": ["Sultan Mas'ud starb; Kalif al-Muqtafi herrschte im Irak allein, nahm Hilla, Kufa und Wasit", "21192405"], "d": ["Mit dem Tod Sultan Mas'uds errichtete Kalif al-Muqtafi li-Amr Allah in Bagdad und im Irak eine vom seldschukischen Einfluss unabhängige Herrschaft; der Wesir des Kalifen nahm Hilla ein, auch Kufa und Wasit wurden erobert.", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Yağıbasan erobert Elbistan", "824708d3"], "d": ["Nach dem Tod Mesuds nahm der Danischmendiden-Melik von Sivas, Yağıbasan, Elbistan ein; die Verwaltung wurde ihm durch Vereinbarung überlassen.", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Seldschukische Befehlshaber nehmen Hille ein, die Mezyedî stehen unter einem Statthalter", "43afd955"], "d": ["Hille wurde von den Befehlshabern des Sultans Muhammed b. Mahmûd eingenommen; die Mezyedî herrschten weiter, unterstanden aber dem Stellvertreter des Sultans.", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Baku unter der Herrschaft der Schirwanschahs – in der Quelle datiertes Zeugnis", "1f2863e4"], "d": ["Die Quelle zeigt die Stadt Baku zu diesem Zeitpunkt unter der Verwaltung der Schirwanschahs; der frühere Besitz ist in der Quelle nicht datiert (der Atlas lässt die Zeit davor leer).", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["Kalif Müstencid nimmt Hille ein, die Mezyedî enden", "4348923c"], "d": ["Truppen des Kalifen Müstencid und der Benî Müntefik besetzten Hille, die Mezyedî wurden zerschlagen.", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Kılıcarslan II. nimmt Elbistan und Darende ein", "7c109007"], "d": ["Kılıcarslan II. nutzte den Streit unter den Danischmendiden und eroberte Elbistan, Darende und die Gegend von Gedük.", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["Rupenî Mleh nimmt Tarsus von Byzanz zurück", "2f98fd11"], "d": ["Rupenî Mleh eroberte mit Hilfe Nûreddin Zengîs Adana, Misis und Tarsus von den Byzantinern zurück.", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["Der Ildeniz Pehlivan nimmt Täbris ein", "f0831f17"], "d": ["Der Ildeniz Pehlivan übernahm Täbris auf friedlichem Weg von den Ahmedîlî und übergab es seinem Bruder Kızılarslan.", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Kılıcarslan II. nimmt Sivas und Niksar von den Danischmendiden", "584575bb"], "d": ["Nach dem Tod Nûreddin Zengîs eroberte Kılıcarslan II. im Sommer 1175 Sivas, Niksar, Tokat und die übrigen Danischmendiden-Gebiete; der Sivas-Zweig endete.", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Kılıcarslan II. nimmt Malatya ein, der Danischmendiden-Zweig endet", "3bdbb060"], "d": ["Nach viermonatiger Belagerung ging Malatya an die Seldschuken über, und der Malatya-Zweig der Danischmendiden endete.", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Selâhaddin nimmt Âmid ein und übergibt es dem Artukiden Nûreddin Muhammed", "8c3cc7bb"], "d": ["Selâhaddîn-i Eyyûbî belagerte und nahm Âmid und übergab es dem artukidischen Emir von Hısnıkeyfâ, Nûreddin Muhammed; die İnaloğulları endeten.", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Rupen III. erobert Adana von den Kreuzfahrern zurück", "e9876f85"], "d": ["Misis, Adana und Tel Hamdûn, die nach Mleh eine Zeit lang an die Kreuzfahrer gefallen waren, eroberte der Rupenî Rupen III. 1184 zurück.", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Tikrit geht an die Abbasiden über", "e8f5aeac"], "d": ["Nach der Herrschaft der Begteginliler kam die Stadt unter die Verwaltung des abbasidischen Kalifats.", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Rükneddin Süleyman Şah II. nimmt Samsun zurück", "0971ebcd"], "d": ["Samsun und die östlichen Schwarzmeergebiete, die während der Bruderkämpfe an die Komnenen gefallen waren, wurden von Süleyman Şah zurückerobert.", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Adana und Tarsus: Das Fürstentum der Rupenî wird zum Armenischen Königreich Kilikien", "de3c4beb"], "d": ["Die Dynastie der Rupenî, die Adana und Tarsus hielt, nahm den Königstitel an; es handelt sich um eine Titeländerung derselben Dynastie, das Gebiet wechselte nicht den Besitzer. Der Krönungstag wurde bei TDV NICHT GEFUNDEN – das Datum wurde vom Beginn des Künye-Eintrags des Armenischen Königreichs Kilikien übernommen (der Künye-Tag ist keine Quelle).", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["Das Kaiserreich Trapezunt wird gegründet – auch Giresun und Sinop gehören zu seinem Gebiet", "a99b6ba0"], "d": ["Nach der Einnahme von Konstantinopel durch die Lateiner floh Aleksios Komnenos nach Trapezunt und rief sich zum Kaiser aus; die Stadt wurde Zentrum des neuen Staates. Der von den Komnenen-Enkeln Aleksios und David gegründete Staat reichte bis Sinop; auch Giresun blieb innerhalb der Grenzen des Kaiserreichs Trapezunt.", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Kütahya unter der Herrschaft des Kaiserreichs Nikaia (Laskariden) – in der Quelle datiertes Zeugnis", "d91fa405"], "d": ["Die Quelle zeigt die Stadt Kütahya zu diesem Zeitpunkt unter der Verwaltung des Kaiserreichs Nikaia (Laskariden); der frühere Besitz ist in der Quelle nicht datiert (der Atlas lässt die Zeit davor leer).", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["Der Ildeniz Ebû Bekir nimmt Maragha ein", "03faed10"], "d": ["Der Ahmedîlî Alâeddin Körpearslan musste die Festung Maragha dem Ildeniz-Atabeg Ebû Bekir überlassen.", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["Die Seldschuken erobern Denizli und Honaz", "1053ccc8"], "d": ["Während der zweiten Herrschaft Gıyâseddin Keyhusrevs I. gingen Denizli und Honaz an die Seldschuken über (byzantinische Quellen nennen 1196, der Artikel „selcuklular“ 603/1207).", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-07-16:0":{"b": ["Kai Chosrau I. Ghiyath ad-Din schlug Maraş erneut den Seldschuken zu", "91b1544e"], "d": ["Kai Chosrau unternahm einen Feldzug gegen die Armenier und schlug Maraş dem seldschukischen Gebiet zu.", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Kastamonu unter der Herrschaft der Çobanoğulları – in der Quelle datiertes Zeugnis", "10b682ba"], "d": ["Die Quelle zeigt die Stadt Kastamonu zu diesem Zeitpunkt unter der Verwaltung der Çobanoğulları; der frühere Besitz ist in der Quelle nicht datiert (der Atlas lässt die Zeit davor leer).", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["İzzeddin Keykâvus I. erobert Sinop", "463ea2b9"], "d": ["Der seldschukische Sultan İzzeddin Keykâvus I. nahm Sinop den Komnenen von Trapezunt ab.", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Alâeddin Keykubad I. nimmt Kalonoros (Alâiye) ein", "5a4d6ac2"], "d": ["Die Festung Kalonoros östlich von Antalya wurde von den Seldschuken eingenommen, wieder aufgebaut und erhielt den Namen Alâiye (der Artikel „alanya“ nennt 1221).", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Celâleddin Hârizmşah annektiert Aserbaidschan", "5b812b99"], "d": ["Celâleddin Hârizmşah gliederte Aserbaidschan und Arrân seinem Gebiet an (regionaler Satz).", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Celâleddin Hârizmşah nimmt Maragha ein", "a55ec004"], "d": ["Celâleddin Hârizmşah eroberte Maragha und machte es zu seinem militärischen und administrativen Zentrum in Aserbaidschan.", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Celâleddin Hârizmşah zieht in Täbris ein", "72904097"], "d": ["Als sich der Atabeg Özbek nach Gandscha zurückzog, zog Celâleddin Hârizmşah in Täbris ein, beherrschte die Stadt und machte sie zu seinem Zentrum.", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Alâeddin Keykubad nimmt Kemah ein", "8c5aa655"], "d": ["Der Kemah-Erzincan-Zweig der Mengücüklüler wurde von Alâeddin Keykubad I., der Kemah belagerte und einnahm, dem seldschukischen Gebiet angegliedert.", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Maragha wird zum zweiten Mal von den Mongolen erobert", "f1320e5d"], "d": ["Am Ende der Herrschaft der Hârizmşah fiel Maragha in die Hände der Mongolen.", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["Aserbaidschan gerät unter mongolische Herrschaft – Täbris wird von den Mongolen besetzt", "3f38ef66"], "d": ["Mit dem Zusammenbruch Celâleddin Hârizmşahs wurde Täbris 1231 von den Mongolen besetzt; die mongolische Herrschaft umfasste im selben Jahr Nord- und Südaserbaidschan (regionaler Satz, nicht stadtspezifisch). In Schirwan (Baku, Schamachi) bestanden die Schirwanschahs unter mongolischer Oberhoheit als lokale Dynastie fort; der Atlas hält diese beiden Orte auf Beschluss Emres in der Farbe der Schirwanschahs (mongolische/ilchanidische Abhängigkeit in der Anmerkung).", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["Der Ayyubide al-Melikü'l-Kâmil nimmt Âmid ein", "9cebe681"], "d": ["al-Melikü'l-Kâmil belagerte Âmid und nahm es den Artukiden ab.", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Alâeddin Keykubad I. nimmt Kütahya dem Kaiserreich Nikaia ab", "e0b9a7f7"], "d": ["Kütahya, das in den Wirren nach 1182 erneut an Byzanz gefallen war, wurde zur Zeit Alâeddin Keykubads I. vom Kaiserreich Nikaia zurückerobert.", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Bedreddin Lü'lü' wird Sultan von Mosul", "73268628"], "d": ["Nach dem Tod des letzten Zengiden-Atabegs wurde Bedreddin Lü'lü' vom Kalifen zum Sultan ausgerufen. (Rebîülevvel 631 / Dezember 1233; der Atlas schreibt entsprechend der Künye mit Jahrespräzision.)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["Die Seldschuken nehmen Harput ein", "3b9391eb"], "d": ["Das Heer Alâeddin Keykubads nahm nach vierundzwanzigtägiger Belagerung die Festung Harput in Besitz; die Artukiden von Harput endeten.", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-07-23:0":{"b": ["Kai Chosrau II. Ghiyath ad-Din eroberte Amid", "c37c3b04"], "d": ["Der anatolische Seldschukensultan Kai Chosrau II. Ghiyath ad-Din nahm Amid den Ayyubiden ab.", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Möngke Khan setzt İftihârüddin als Statthalter in Qazvin ein", "fc650d13"], "d": ["Der Großkhan der Mongolen, Möngke, ernannte einen Statthalter für Qazvin; die Zeit der İftihârî begann.", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Ankunft Hülâgûs: Qazvin und Nachitschewan gehen in ilchanidische Verwaltung über", "24673608"], "d": ["Mit der Ankunft Hülâgûs in Iran ging die mongolische Verwaltung auf das Ilchanat über; Qazvin und Nachitschewan kamen unter ilchanidische Verwaltung (Grenze nach Regel 5, nicht Quellentag). In Schirwan (Baku, Schamachi) brachte die mongolische Besetzung schwere Zerstörungen, doch die Schirwanschahs bestanden als lokale Dynastie fort; der Atlas hält diese beiden Orte in der Farbe der Schirwanschahs (Beschluss Emres).", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["Die Mongolen besetzen Tikrit", "60af2df0"], "d": ["Während des mongolischen Einfalls wurde Tikrit besetzt und geplündert; die Stadt schied aus der abbasidischen Verwaltung aus.", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Hülâgû zieht von Hamadan nach Bagdad", "5f0c77b5"], "d": ["Hülâgû brach von Hamadan, wo sich sein Tross befand, zum Feldzug gegen Bagdad auf (Zeugnis der ilchanidischen Herrschaft).", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Boğatimur nimmt Kufa und Basra ein", "dec82b4e"], "d": ["Die mongolischen Truppen unter Boğatimur eroberten Kufa, Wasit und Basra.", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["Der Irak fällt in die Hände der Mongolen (regional)", "7b990281"], "d": ["Mit der Besetzung Bagdads durch Hülâgû 1258 wurde der abbasidische Staat gestürzt, und der Irak fiel in die Hände der Mongolen.", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Maraş wird den Armeniern überlassen", "6161f1a5"], "d": ["Als İmâdüddin aus der Familie Hüsâmeddin keine Unterstützung fand, verließ er Maraş zugunsten der Kilikischen Armenier.", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Wasit geht in ilchanidische Herrschaft über", "fbdf83fc"], "d": ["Mit der Eroberung des Irak durch die Ilchane kam Wasit unter deren Verwaltung.", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["Die Mongolen nehmen Bagdad ein; Ende des abbasidischen Kalifats", "41c34bd4"], "d": ["Die Mongolen unter Hülâgû griffen Bagdad an, Kalif Müsta‘sım ergab sich; die Stadt ging in ilchanidische Herrschaft über.", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["Die Mongolen nehmen Mosul ein, die Dynastie der Lü'lü' endet", "035d0121"], "d": ["Mosul von al-Melikü's-Sâlih İsmâil, der auf Seiten Baybars' stand, wurde von den Mongolen zerstört; er selbst wurde in Anwesenheit Hülâgûs getötet.", "69cc41a9"]},
"OLAYLAR_T5_1000B:1069-10-20:0":{"b": ["Die Freitagspredigt in Mekka wurde von den Fatimiden auf den abbasidischen Kalifen und Sultan Alp Arslan umgestellt", "df951887"], "d": ["Als wegen der Hungersnot in Ägypten keine Vorräte mehr eintrafen, ließ der Emir von Mekka, Abu Haschim Muhammad b. Dscha'far, die Predigt im Namen des abbasidischen Kalifen al-Qa'im bi-Amr Allah und des Seldschukensultans Alp Arslan verlesen; Mekka kam unter die Oberhoheit der Großseldschuken.", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Atsız b. Uvak nimmt Damaskus ein", "8eea047f"], "d": ["Atsız eroberte Syrien und ließ die Chutba auf den Namen des abbasidischen Kalifen und Melikşahs sprechen.", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["Der Emir von Mekka, Ebû Hâşim, lässt die Chutba wieder auf den Namen des fatimidischen Kalifen sprechen", "85b6c0c0"], "d": ["Trotz der Bemühungen Melikşahs, den sunnitischen Einfluss zu festigen, begann der Emir von Mekka erneut, die Chutba auf den Namen der Fatimiden sprechen zu lassen; Mekka kehrte unter fatimidische Oberhoheit zurück.", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Tutuş zieht in Damaskus ein, die Syrischen Seldschuken entstehen", "b48b38be"], "d": ["Tutuş zog in die Stadt ein und gründete den Staat der Syrischen Seldschuken.", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["Der Emir von Mekka erklärt dem abbasidischen Kalifen Muktedî und Sultan Melikşah seine Gefolgschaft", "38a430a5"], "d": ["Der Emir von Mekka unterstellte sich erneut dem abbasidischen Kalifen und dem seldschukischen Sultan; diese Bindung dauerte bis zum Tod Melikşahs (1092).", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["Nach dem Tod Sultan Melikşahs geht die Chutba in Mekka wieder an die Fatimiden", "195a27cd"], "d": ["Als der seldschukische Sultan Melikşah starb, ließ der Emir von Mekka die Chutba wieder auf den Namen des fatimidischen Kalifen sprechen; Mekka kam unter fatimidische Oberhoheit.", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["Nach der Niederlage bei Dorylaion kehrt Eskişehir zu Byzanz zurück", "3f381ee4"], "d": ["Nach dem Rückzug Kılıcarslans I. vor den Kreuzfahrern kam die Stadt wieder unter byzantinische Verwaltung.", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Tuğtegin gründet das Atabegat von Damaskus", "f26729c0"], "d": ["Nach dem Tod Dukaks gründete der Atabeg Tuğtegin die Dynastie der Börî.", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["Die Almohaden nehmen Meknès ein", "ee976b41"], "d": ["Nach langem Widerstand kam die Stadt unter almohadische Herrschaft und wurde geplündert.", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Nûreddin Zengî nimmt Damaskus ein", "a4fd8b58"], "d": ["Nûreddin Mahmud brachte Damaskus unter seine Herrschaft.", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Das Ende der fatimidischen Verwaltung in Ägypten, die Ayyubiden übernehmen – Alexandria, Fayyum und Mekka (Hidschaz)", "1c565534"], "d": ["Mit dem Wesirat Selâhaddins und dem Tod des fatimidischen Kalifen Âdıd (567/1171) ging Ägypten an die Ayyubiden über; Alexandria und Fayyum kamen unter ayyubidische Verwaltung. Der Tag fehlt in der Quelle – er wurde vom Ende der fatimidischen Künye übernommen (der Künye-Tag ist keine Quelle). Auch der Hidschaz kam unter ayyubidische Verwaltung; die Oberhoheit über Mekka ging von den Fatimiden auf die Ayyubiden über (Oberherrenmodell, Emre #23).", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Selâhaddin nimmt Damaskus ein", "dfdb11ce"], "d": ["Nach dem Tod Nûreddins ging die Stadt an Selâhaddîn-i Eyyûbî über.", "a20855b8"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Nach Myriokephalon räumt Byzanz Dorylaion", "24aef255"], "d": ["Nach der Niederlage bei Myriokephalon ließ Manuel vertragsgemäß die Befestigungen von Dorylaion schleifen und räumte die Stadt; die Türken nannten sie fortan Eskişehir.", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Amasya wird dem seldschukischen Gebiet angegliedert", "cf56b964"], "d": ["Kılıcarslan II. gliederte die Danischmendiden-Gebiete (einschließlich Amasya) dem seldschukischen Land an.", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Die Brüder Asen nehmen Nordbulgarien ein; Byzanz erkennt das Zweite Bulgarische Reich an", "ff0554e9"], "d": ["Die Brüder Petar und Asen eroberten mit kumanischer Unterstützung Nordbulgarien zurück; mit dem Frieden von 1187 erkannte Byzanz das Zweite Bulgarische Reich an.", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["Serbien festigt seine Herrschaft in Zeta", "794c821d"], "d": ["1189 festigte Serbien seine Herrschaft über Zeta (einschließlich der Küste von Kotor); Zeta wurde ein Sonderstatus zuerkannt.", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Guy de Lusignan kauft Zypern, Nikosia wird Hauptstadt", "11017aea"], "d": ["Guy de Lusignan kaufte die Insel von den Templern und machte Nikosia zur Hauptstadt.", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Kaloyan erobert Warna", "1237fe7f"], "d": ["Die Bulgaren unter Zar Kaloyan nahmen im März 1201 Warna von Byzanz ein; die Stadt blieb im 13.–14. Jahrhundert innerhalb der Grenzen des Bulgarischen Reiches.", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Nischapur wird endgültig den Hârizmşah angegliedert", "fa4a6cd2"], "d": ["Alâeddin Muhammed b. Tekiş gliederte die Stadt endgültig dem Gebiet der Hârizmşah an.", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["Die Halbinsel Gallipoli kommt unter lateinische Verwaltung", "27308f59"], "d": ["Nach dem Vierten Kreuzzug ging Gallipoli mit Umgebung 1204 in die Verwaltung der Lateiner über.", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["Das Despotat Epirus wird gegründet – Ioannina wird Zentrum, Naupaktos kommt zum Despotat", "d7966877"], "d": ["Nach dem Vierten Kreuzzug gründete Michael Angelos das Despotat Epirus; Ioannina wurde Zentrum des Despotats, auch Naupaktos blieb innerhalb des Despotatsgebiets.", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["Kreta wird an Venedig verkauft", "f1760e84"], "d": ["Markgraf Bonifatius von Montferrat überließ Kreta mit dem Abkommen vom 12. August 1204 für 100.000 Silber an Venedig.", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["Mansûra wird gegründet", "342a6f47"], "d": ["al-Melikü'l-Kâmil gründete Mansûra als Feldlager gegen die Kreuzfahrer, die Damiette besetzt hatten.", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["Die Mongolen nehmen Nischapur ein", "0e73f075"], "d": ["Beim mongolischen Einfall wurde die Stadt zerstört.", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["Der Rasulide Nûreddin Ömer bringt den Jemen unter seine Verwaltung", "ee1ec7ab"], "d": ["Nach dem Tod des letzten jemenitischen Ayyubiden al-Mes‘ûd übernahm Nûreddin Ömer die Herrschaft im Jemen.", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["Kaiser Vatatzes von Nikaia erobert Gallipoli zurück", "a6936e33"], "d": ["Kaiser Ioannes III. Vatatzes von Nikaia eroberte Gallipoli von den Lateinern zurück (1235).", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["Die Mongolen erobern Amasya", "783bcd0c"], "d": ["Nach Köse Dağ nahmen die Mongolen die Stadt ein; mongolische Statthalter verwalteten sie.", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Vatatzes setzt nach Thrakien über: Adrianopel und Thessaloniki werden dem Kaiserreich Nikaia angegliedert", "0bf61ca5"], "d": ["Der Herrscher von Nikaia, Ioannes III. Vatatzes, setzte 1246 nach Thrakien über und nahm die von den Bulgaren besetzten Gebiete und Thessaloniki ein.", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["Die rasulidische Herrschaft wird in Mekka anerkannt – Nûreddin Ömer fällt einem Attentat zum Opfer", "d7e03c21"], "d": ["Als der rasulidische Sultan des Jemen, Nûreddin Ömer, in Cened ermordet wurde (Februar 1250), wurde die Herrschaft seines Staates zwischen Mekka und Hadramaut anerkannt; im Jahr des Endes des ayyubidischen Sultanats erscheint Mekka unter rasulidischer Oberhoheit.", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["Der Mamlukenstaat wird in Ägypten gegründet – Alexandria, Mansûra und Fayyum gehen an die Mamluken", "230c1a11"], "d": ["Nach Turan Şah wurde mit Şecerüddür und İzzeddin Aybek die mamlukische Herrschaft begründet; die ägyptischen Städte (Alexandria, Mansûra, Fayyum) kamen unter mamlukische Verwaltung. Die Quelle nennt für Aybeks Thronbesteigung den 3. Juli 1250; der Atlas übernahm den Tag vom Ende der ayyubidischen Künye (30. April 1250) – der Künye-Tag ist keine Quelle, die Abweichung wurde gemeldet.", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["Der Ayyubide von Aleppo, en-Nâsır Yûsuf, gewinnt die Herrschaft über Damaskus", "d585985d"], "d": ["Während in Ägypten die mamlukische Herrschaft entstand, nahm der Herrscher von Aleppo, en-Nâsır Yûsuf, Damaskus ein (648/1250).", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Jerusalem wird durch Frieden den Mamluken überlassen", "50d53fac"], "d": ["Durch einen unter Vermittlung des Kalifen geschlossenen Frieden wurde Jerusalem den Mamluken überlassen.", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Jerusalem geht wieder an die Ayyubiden", "fdeedd4a"], "d": ["Palästina und Jerusalem fielen erneut in die Hände der syrischen Ayyubiden.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Die Mongolen nehmen Damaskus ein", "430bdfea"], "d": ["Beim Syrienfeldzug Hülâgûs ging Damaskus an die Mongolen.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Schlacht von Ain Dschalut: Damaskus und Jerusalem gehen an die Mamluken", "40ebd7b7"], "d": ["Kutuz besiegte die Mongolen bei Ain Dschalut (25. Ramazan 658 / 3. September 1260); der größte Teil Syriens, Damaskus und Jerusalem fielen in die Hände der Mamluken, die ayyubidische Dynastie endete.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Baybars belebt das abbasidische Kalifat in Kairo wieder – Mekka und Medina werden den Mamluken unterstellt", "a5128a1e"], "d": ["Baybars rief den aus der Zerstörung Bagdads entkommenen Abbasiden Ahmed in Kairo zum Kalifen aus und huldigte ihm; als Schutzherr des Kalifats unterstellte er auch die beiden Heiligen Stätten (Haramain) der mamlukischen Oberhoheit. Der Tag ist der der Wiederbelebung des Kalifats; der Tag der Unterstellung Mekkas und Medinas fehlt in der Quelle (Untergrenze).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["Nikaiische Truppen ziehen in Konstantinopel ein – das Byzantinische Reich wird wiedererrichtet", "81741490"], "d": ["Nikaiische Truppen zogen am 25. Juli 1261 in Konstantinopel ein und beendeten die lateinische Herrschaft; die Gebiete des laskaridischen (nikaiischen) Staates – Bursa, Izmir, Çimpe, Adrianopel, Thessaloniki – wurden wieder zum Byzantinischen Reich. Der Atlas zeigt an diesen Punkten die Zeit des Kaiserreichs Nikaia vor 1261 nur dort, wo sie in der Quelle namentlich genannt wird.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Charles d'Anjou nimmt Durrës und Krujë ein", "082a86b8"], "d": ["Charles aus dem Hause Anjou nahm 1271–1272 Durrës und Krujë ein und ließ die alte Festung wieder aufbauen.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Die Sizilianer besetzen die Insel Djerba", "daab5ad2"], "d": ["Die Insel Djerba wurde im Jahr 683 (1284–85) von den Sizilianern besetzt; sie gehörte zunächst dem Papsttum als Lehen, später dem Königreich Sizilien.", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Ioannina wird wieder dem Byzantinischen Reich angegliedert", "60016303"], "d": ["Ioannina, das in der zweiten Hälfte des 13. Jahrhunderts mehrfach den Besitzer gewechselt hatte, wurde 1318 wieder Byzanz angegliedert, behielt aber bis zu einem gewissen Grad seine Autonomie; das Zentrum des Despotats Epirus verlagerte sich nach Arta.", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["Die Bevölkerung von Djerba vertreibt die Sizilianer von der Insel", "ff71985e"], "d": ["Die Inselbevölkerung, die sich gegen die schlechte Verwaltung der sizilianischen Statthalter erhob, vertrieb 1334 die Sizilianer; Djerba kam wieder unter hafsidische Verwaltung.", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Charles Thopia gewinnt die Herrschaft über Krujë", "4e40583d"], "d": ["Nach dem Tod des Zaren Dušan (1355) gewann der Albaner Charles Thopia die Herrschaft über Krujë.", "7af64cd2"]}
});
